mapper.select:
SELECT location_nm
FROM tb_location
WHERE location_id = #{locationId,jdbcType=BIGINT}

SELECT ward_id
FROM tb_location
WHERE location_id = #{locationId,jdbcType=BIGINT}

SELECT EXISTS (
    SELECT 1
    FROM tb_caregiver
    WHERE location_id = #{locationId,jdbcType=BIGINT}
      AND use_yn = 'Y'

      AND caregiver_id <> #{caregiverId}

)

SELECT EXISTS (
    SELECT 1
    FROM tb_caregiver
    WHERE hosp_div_id = #{hospitalDomain}
      AND phone_no = #{phoneNumber}
      AND use_yn = 'Y'

      AND caregiver_id <> #{caregiverId}

)

mapper.update:
UPDATE tb_caregiver
SET location_id = #{locationId,jdbcType=BIGINT},
    upd_dt = NOW()
WHERE hosp_div_id = #{hospitalDomain}
  AND caregiver_id = #{caregiverId}
  AND use_yn = 'Y'

UPDATE tb_caregiver
SET phone_no = #{phoneNumber},
    upd_dt = NOW()
WHERE hosp_div_id = #{hospitalDomain}
  AND caregiver_id = #{caregiverId}
  AND use_yn = 'Y'

UPDATE tb_caregiver
SET use_yn = #{toUseYn},
    upd_dt = NOW()
WHERE hosp_div_id = #{hospitalDomain}
  AND caregiver_id = #{caregiverId}
  AND use_yn = #{fromUseYn}

mapper.delete:
DELETE FROM tb_caregiver
WHERE hosp_div_id = #{hospitalDomain}
  AND caregiver_id = #{caregiverId}
  AND use_yn = 'N'
